import os, re, json

d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
lines = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().split('\n')

# Parse all messages and extract grids from message content
G = {}
for line in lines:
    try:
        msg = json.loads(line)
        # Get the text content from user or tool responses
        if isinstance(msg, dict):
            content_list = msg.get('message', {}).get('content', [])
            for item in content_list:
                if item.get('type') == 'text':
                    text = item.get('text', '')
                    # Look for Demo/Test input patterns
                    for pattern_match in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', text):
                        key = pattern_match.group(1)
                        h, w = int(pattern_match.group(2)), int(pattern_match.group(3))

                        # Extract the grid data after this marker
                        start_pos = pattern_match.end()
                        remaining = text[start_pos:]

                        # Parse rows until we hit a non-grid line
                        rows = []
                        for match in re.finditer(r'^([0-9 ]{1,30})$', remaining, re.MULTILINE):
                            row_line = match.group(1).split()
                            if len(row_line) == w:
                                rows.append([int(x) for x in row_line])
                            else:
                                break

                        if len(rows) > 0:
                            G[key] = rows
    except:
        pass

print("Loaded grids:", list(G.keys()))
for k in G:
    g = G[k]
    print(f"  {k}: {len(g)}x{len(g[0]) if g else 0}")

import os, re, json

d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
