# Extract all grids from messages
G = {}

for i, line in enumerate(lines):
    try:
        msg = json.loads(line)
        if isinstance(msg, dict):
            # Get text content
            content_list = msg.get('message', {}).get('content', [])
            for item in content_list:
                if item.get('type') == 'text':
                    text = item.get('text', '')

                    # Search for demo/test patterns in this exact format
                    pattern = r"(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):([0-9 ]+)\n"
                    for m in re.finditer(pattern, text, re.MULTILINE | re.DOTALL):
                        key = m.group(1)
                        h, w = int(m.group(2)), int(m.group(3))
                        grid_str = m.group(4).strip()

                        # Parse into rows
                        rows = []
                        num_lines_in_grid = min(h, len(grid_str.split('\n')))
                        for row_line in grid_str.split('\n')[:h]:
                            row_vals = row_line.split()
                            if len(row_vals) >= w and all(x.isdigit() for x in row_vals[:w]):
                                rows.append([int(x) for x in row_vals[:w]])

                        if rows:
                            G[key] = rows
                    except Exception as e:
                        print(f"Error parsing line {i}: {e}")
                        continue

    except Exception as e:
        print(f"Error processing line {i}: {e}")

print("Loaded grids:", list(G.keys()))
