# For each cell, find if it's on a "line" of any 3 belonging to a center
# If on multiple lines, use some priority (maybe larger center value wins?)

# Get the extent of each cluster
def get_cluster_3s(grid, r, c, threshold=3):
    """Get all cells within Manhattan distance threshold of center"""
    cells = []
    for dr in range(-threshold, threshold+1):
        for dc in range(-threshold, threshold+1):
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                # Check if this cell contains a 3 AND is closer to this center than others
                dist_to_center = abs(nr-r) + abs(nc-c)
                if grid[nr][nc] == 3:
                    cells.append(((nr, nc), dist_to_center))
    return cells

# Actually let me try a simpler model:
# A cell gets value C if it's on the same row OR same column as ONE of C's 3-arm positions
# And there's no OTHER cluster's 3 on that same row/col between this cell and center

centers = [(2,2,5), (3,8,6), (6,5,8)]  # (row, col, value)

# Get all 3s and their closest center
all_threes_with_centers = []
for r in range(10):
    for c in range(10):
        if demo2_in[r][c] == 3:
            best_center = None
            min_dist = float('inf')
            for cr, cc, cv in centers:
                dist = abs(r-cr) + abs(c-cc)
                if dist < min_dist:
                    min_dist = dist
                    best_center = (cr, cc, cv)
            all_threes_with_centers.append((r, c, *best_center))

print("3s and their assigned centers:")
for item in all_threes_with_centers:
    print(f"  {item}")

# Now check: for each cell, what should it become?
# Rule hypothesis: if cell is on same row/col as ANY 3 that belongs to a center,
# fill it with that center's value (but handle conflicts by using closest center)

def predict_value(r, c, grid_in, grid_out, centers):
    """Predict what value cell (r,c) should have"""
    if grid_in[r][c] > 0 and grid_in[r][c] != 3:
        # Keep the original value (center itself stays)
        return grid_in[r][c]

    if grid_in[r][c] == 3:
        # 3s stay as 3s
        return 3

    # Find all clusters that have a 3 on this row or column
    possible_values = []
    for cr, cc, cv in centers:
        # Check if any 3 belonging to this center is on row r or column c
        for tr, tc, _, vc in all_threes_with_centers:
            if tr == r or tc == c:
                if vc == cv:
                    possible_values.append(cv)

    if possible_values:
        # Return most frequent value
        return max(set(possible_values), key=possible_values.count)
    else:
        return 0

