# Hypothesis v13: From each center, expand OUTWARD in 4 cardinal directions
# Fill until hitting a 3 or boundary. Columns have higher priority than rows.

def predict_v13(r, c, grid_in, centers):
    if grid_in[r][c] > 0 and grid_in[r][c] != 3:
        return grid_in[r][c]
    if grid_in[r][c] == 3:
        return 3

    result = None  # Will track what value we assign (column wins over row)

